## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## DBsubject(Linear algebra)
## DBchapter(Linear transformations)
## DBsection(One-to-one and onto)
## Date(July 2013)
## Institution(Hope College)
## Author(Paul Pearson)
## Level(3)

DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "MatrixUnits.pl",
  "VectorListCheckers.pl",
  "parserRadioButtons.pl",
  "unionLists.pl",
  "PGcourse.pl"
);

TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');

do {

foreach my $i (1..3) {
  foreach my $j (1..2) {
    $a[$i][$j] = non_zero_random(-5,5,1);
  }
}

$A = Matrix([
[ $a[1][1], $a[1][2] ],
[ $a[2][1], $a[2][2] ],
[ $a[3][1], $a[3][2] ],
]);

} until ( $a[1][1] * $a[2][2] != $a[1][2] * $a[2][1] );

($m,$n) = $A->dimensions;

$x = random(-1,1,2) * random(6,9,1);
$y = random(-1,1,2) * random(6,9,1);


$X = Matrix([
[$x],
[$y]
]);

$AX = $A * $X;

$mc = RadioButtons(
    [ "one-to-one", "onto", "bijective", "none of these" ],
    "one-to-one",
    last =>     [ "one-to-one", "onto", "bijective", "none of these" ],
#    labels => [ "one-to-one", "onto", "bijective", "none of these" ], 
);

Context()->texStrings;
BEGIN_TEXT
Let \( f : \mathbb{R}^{$n} \to \mathbb{R}^{$m} \) be the linear transformation determined by 
\[
f
\left( 
\begin{bmatrix}
1 \\ 0
\end{bmatrix}
\right)
=

\begin{bmatrix}
$a[1][1] \\ 
$a[2][1] \\ 
$a[3][1] 
\end{bmatrix},
\ \ \ \ \
f
\left( 
\begin{bmatrix}
0 \\ 1
\end{bmatrix}
\right)
=
\begin{bmatrix}
$a[1][2] \\ 
$a[2][2] \\ 
$a[3][2] 
\end{bmatrix}
.
\]

\{ BeginList('OL',type=>'a') \}

$ITEM
Find 
\( \displaystyle
f
\left( 
\begin{bmatrix}
$x \\ $y
\end{bmatrix}
\right)
\).
$BR
$BR
\( \displaystyle
f
\left( 
\begin{bmatrix}
$x \\ $y
\end{bmatrix}
\right)
 =
\) 
\{ $AX->ans_array(10) \}.

$ITEMSEP
$ITEM
Find the matrix of the linear transformation \( f \).
$BR
$BR
\( \displaystyle
f
\left( 
\begin{array}{c}
x \\ y
\end{array}
\right)
 = \)
\{ $A->ans_array(10) \}
\( \displaystyle 
\left\lbrack
\begin{array}{c}
x \\ y
\end{array}
\right\rbrack.
\)

$ITEMSEP
$ITEM 
The linear transformation \( f \) is 
$BR
\{ $mc->buttons() \}
\{ EndList('OL') \}
END_TEXT
Context()->normalStrings;

ANS( $AX->cmp() );

ANS( $A->cmp() );

ANS( $mc->cmp() );


COMMENT('Always injective.');

ENDDOCUMENT();

## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## DBsubject(Linear algebra)
## DBchapter(Linear transformations)
## DBsection(One-to-one and onto)
## Date(July 2013)
## Institution(Hope College)
## Author(Paul Pearson)
## Level(3)

DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "MatrixUnits.pl",
  "VectorListCheckers.pl",
  "parserRadioButtons.pl",
  "unionLists.pl",
  "PGcourse.pl"
);

TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');

$a1 = non_zero_random(-4,4,1);
$a2 = non_zero_random(-4,4,1);
$a3 = non_zero_random(-4,4,1);

$s = random(-1,1,2) * random(2,5,1);
$t = random(-1,1,2) * random(2,5,1);

$a[1][1] = $s * $a1;
$a[2][1] = $s * $a2;
$a[3][1] = $s * $a3;

$a[1][2] = $t * $a1;
$a[2][2] = $t * $a2;
$a[3][2] = $t * $a3;


$A = Matrix([
[ $a[1][1], $a[1][2] ],
[ $a[2][1], $a[2][2] ],
[ $a[3][1], $a[3][2] ],
]);

($m,$n) = $A->dimensions;

$x = non_zero_random(-4,4,1);
$y = non_zero_random(-4,4,1);

$X = Matrix([
[$x],
[$y]
]);

$AX = $A * $X;

$mc = RadioButtons(
    [ "one-to-one", "onto", "bijective", "none of these" ],
    "none of these",
    last =>     [ "one-to-one", "onto", "bijective", "none of these" ],
#    labels => [ "one-to-one", "onto", "bijective", "none of these" ], 
);

Context()->texStrings;
BEGIN_TEXT
Let \( f : \mathbb{R}^{$n} \to \mathbb{R}^{$m} \) be the linear transformation determined by 
\[
f(\vec{e}_1)
=
\begin{bmatrix}
$a[1][1] \\ 
$a[2][1] \\ 
$a[3][1] 
\end{bmatrix}
,
\ \ \ \ \
f(\vec{e}_2)
=

\begin{bmatrix}
$a[1][2] \\ 
$a[2][2] \\ 
$a[3][2] 
\end{bmatrix}.
\]

\{ BeginList('OL',type=>'a') \}

$ITEM 
Find 
\( \displaystyle
f
\left( 
\begin{bmatrix}
$x \\ $y
\end{bmatrix}
\right)
\).
$BR
$BR
\( \displaystyle
f
\left( 
\begin{bmatrix}
$x \\ $y
\end{bmatrix}
\right)
 =
\) 
\{ $AX->ans_array(10) \}.

$ITEMSEP
$ITEM 
Find the matrix of the linear transformation \( f \).
$BR
$BR
\( \displaystyle
f
\left( 
\begin{bmatrix}
x \\ y
\end{bmatrix}
\right)
 = \)
\{ $A->ans_array(10) \}
\( \displaystyle 
\begin{bmatrix}
x \\ y
\end{bmatrix}
\)

$ITEMSEP
$ITEM
The linear transformation \( f \) is 
$BR
\{ $mc->buttons() \}
\{ EndList('OL') \}
END_TEXT
Context()->normalStrings;

ANS( $AX->cmp() );

ANS( $A->cmp() );

ANS( $mc->cmp() );


COMMENT('Not one-to-one and not onto.');

ENDDOCUMENT();

## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## Tagged by tda2d

## DBsubject(Linear algebra)
## DBchapter(Euclidean spaces)
## DBsection(Span)
## Institution(TCNJ)
## Level(3)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('2.2')
## Problem1('')
## KEYWORDS('vector' 'linear' 'combination' 'span')

DOCUMENT();        # This should be the first executable line in the problem.
loadMacros(
  "PGstandard.pl",
  "PGchoicemacros.pl",
  "PGgraphmacros.pl",
  "PGmatrixmacros.pl",
  "PGcourse.pl"
);
 
TEXT(beginproblem());    
# Do not show which answers are incorrect.
$showPartialCorrectAnswers = 0;

foreach $i (1..3) { 
	$a1[$i] = non_zero_random(-3,3,1);
        $a2[$i] = (0);
}
$m = non_zero_random(-2,2,1);
$n = random(3,4,1)*random(-1,1,2);
foreach $i (1..3) { 
        $a3[$i] = $m*$a1[$i];
        $a4[$i] = $n*$a1[$i];
}

foreach $i (1..3) {
        $b1[$i] = non_zero_random(-3,3,1);
}
$o = random(2,4,1)*random(-1,1,2);
$p = random(-1,1,2);
foreach $i (1..2) {
        $b2[$i] = $o*$b1[$i];
}
$b2[3] = $o*$b1[3]+$p;
$q = non_zero_random(-2,2,1);
$r = non_zero_random(-2,2,1);
$s = non_zero_random(-2,2,1);
$t = random(3,4,1)*random(-1,1,2);
foreach $i (1..3) {
        $b3[$i] = $q*$b1[$i]+$r*$b2[$i];
        $b4[$i] = $s*$b1[$i]+$t*$b2[$i];
}

foreach $i (1..3) {
        $c1[$i] = non_zero_random(-3,3,1);
        $c2[$i] = random(5,7,2)*random(-1,1,2);
}
$c2[3] += 1 unless (
	$c1[2]*$c2[3] - $c1[3]*$c2[2]
);
$e = non_zero_random(-2,2,1);
$f = non_zero_random(-2,2,1);
$g = random(-1,1,2);
foreach $i (2..3) {
        $c3[$i] = $e*$c1[$i]+$f*$c2[$i];
        $c4[$i] = non_zero_random(-3,3,1);
}
$c3[1] = $e*$c1[1]+$f*$c2[1]+$g;
$c4[1] = 0;

# Make a new checkbox multiple choice
$tf = new_pop_up_select_list();
$tf->ra_pop_up_list(["?"=>"Select an Answer", "Line" => "Line",
                        "Plane" => "Plane", "R^3" => "R^3"]);
# $cmc now "contains" the checkbox multiple choice object.

# Insert some  questions and matching answers in the q/a list

$tf -> qa ( mbox( '\(\vec{v_1} = \)',display_matrix([[$a1[1]], [$a1[2]], [$a1[3]]]), ', ', 
	 '\(\vec{v_2} = \)',display_matrix([[$a2[1]], [$a2[2]], [$a2[3]]]), ', ', 
         '\(\vec{v_3} = \)',display_matrix([[$a3[1]], [$a3[2]], [$a3[3]]]), ', ', 
	 '\(\vec{v_4} = \)',display_matrix([[$a4[1]], [$a4[2]], [$a4[3]]]), ),
"Line",            
mbox( '\(\vec{v_1} = \)',display_matrix([[$b1[1]], [$b1[2]], [$b1[3]]]), ', ', 
	 '\(\vec{v_2} = \)',display_matrix([[$b2[1]], [$b2[2]], [$b2[3]]]), ', ', 
         '\(\vec{v_3} = \)',display_matrix([[$b3[1]], [$b3[2]], [$b3[3]]]), ', ', 
	 '\(\vec{v_4} = \)',display_matrix([[$b4[1]], [$b4[2]], [$b4[3]]]), ),
"Plane",
mbox( '\(\vec{v_1} = \)',display_matrix([[$c1[1]], [$c1[2]], [$c1[3]]]), ', ', 
	 '\(\vec{v_2} = \)',display_matrix([[$c2[1]], [$c2[2]], [$c2[3]]]), ', ', 
         '\(\vec{v_3} = \)',display_matrix([[$c3[1]], [$c3[2]], [$c3[3]]]), ', ', 
	 '\(\vec{v_4} = \)',display_matrix([[$c4[1]], [$c4[2]], [$c4[3]]]), ),
"R^3",
                       
);

$tf->choose(3);

# Insert some incorrect answers

# Print the text using $mc->print_q for the questions and
# $mc->print_a to print the answers.
BEGIN_TEXT

For each of the following sets of vectors, let 
\(W= \text{ span} \left\lbrace \vec{v_1}, \vec{v_2}, \vec{v_3}, \vec{v_4} \right\rbrace\).
Is the subspace \(W\) a line, plane, or \( {\mathbb R}^3\)?
$BR
$BR

 \{ $tf -> print_q \}

END_TEXT

# Enter the correct answers to be checked against the answers to the students.
ANS(str_cmp( $tf->ra_correct_ans )   ) ;

ENDDOCUMENT();

## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## Tagged by cmd6a 4/29/06

## DBsubject(Linear algebra)
## DBchapter(Euclidean spaces)
## DBsection(Basis and dimension)
## Date(July 2013)
## Institution(Rochester and Hope College)
## Author(Paul Pearson)
## MLT(basis_from_dependent_set)
## MO(1)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('4.2')
## Problem1('')

DOCUMENT();
loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "parserMultiAnswer.pl",
  "MatrixCheckers.pl",
  "PGcourse.pl"
);
TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');

foreach $i (1..3) { 
	$u[$i] = non_zero_random(-3,3,1);
	$v[$i] = non_zero_random(-3,3,1);
}

$tag = random(1,3,1);
$v[$tag] = 0;

$m = non_zero_random(-2,2,1);
$n = non_zero_random(-2,2,1);

foreach $i (1..3) { 
        $w[$i] = $m*$u[$i] + $n*$v[$i];
}

$U = Matrix([[$u[1]], [$u[2]], [$u[3]]]);
$W = Matrix([[$w[1]], [$w[2]], [$w[3]]]);
$V = Matrix([[$v[1]], [$v[2]], [$v[3]]]);

$basis1 = $U;
$basis2 = $V;

$multians = MultiAnswer($basis1, $basis2)->with(
  singleResult => 1,
  separator => ',',
  tex_separator => ',',
  allowBlankAnswers=>0,
  checker => ~~&basis_checker_columns,
);


Context()->texStrings;
BEGIN_TEXT
Let \(W\) be the subspace of \( {\mathbb R}^3\) spanned by the following three vectors.
$BR

\[ 
$U, \ \ \ \ 
$W, \ \ \ \
$V. 
\]

It turns out that \(W\) is a plane.  Find a subset of those vectors that form a basis for \(W\).


$PAR
$BCENTER
\(\Bigg\lbrace\) 
\{ $multians->ans_array \}, 
\{ $multians->ans_array \} 
\(\Bigg\rbrace.\)
$ECENTER
END_TEXT
Context()->normalStrings;

ANS($multians->cmp);
;

ENDDOCUMENT();

## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## Tagged by cmd6a 4/29/06

## DBsubject(Linear algebra)
## DBchapter(Euclidean spaces)
## DBsection(Basis and dimension)
## Date(July 2013)
## Institution(Rochester and Hope College)
## Author(Paul Pearson)
## MLT(basis_from_dependent_set)
## MO(1)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('4.2')
## Problem1('')

DOCUMENT();
loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "parserMultiAnswer.pl",
  "MatrixCheckers.pl",
  "PGchoicemacros.pl",
  "PGcourse.pl"
);
TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');

foreach $i (1..4) { 
	$a[1][$i] = non_zero_random(-3,3,1);
	$a[2][$i] = non_zero_random(-3,3,1);
	$a[5][$i] = non_zero_random(-3,3,1);
}

$tag1 = random(1,3,1);
$tag2 = random($tag1+1,4,1);

$a[2][$tag1] = 0;
$a[5][$tag1] = 0;
$a[5][$tag2] = 0;

$m = non_zero_random(-2,2,1);
$n = non_zero_random(-1,1,1);
$p = random(-1,1,1);

$s = non_zero_random(-2,2,1);
$t = non_zero_random(-1,1,1);

foreach $i (1..4) { 
	$a[4][$i] = $m*$a[1][$i] + $n*$a[2][$i] + $p*$a[5][$i];
	$a[3][$i] = $s*$a[1][$i] + $t*$a[5][$i];
}

@slice = NchooseK(4,4); 

foreach $i (1..4) {
	foreach $j (1..4) { 
		$v[$i][$j] = $a[$slice[$i-1]+1][$j];
	}
}

$V1 = Matrix([[$v[1][1]], [$v[1][2]], [$v[1][3]], [$v[1][4]]]);
$V2 = Matrix([[$v[2][1]], [$v[2][2]], [$v[2][3]], [$v[2][4]]]);
$V3 = Matrix([[$v[3][1]], [$v[3][2]], [$v[3][3]], [$v[3][4]]]);
$V4 = Matrix([[$v[4][1]], [$v[4][2]], [$v[4][3]], [$v[4][4]]]);



$basis1 = Matrix([ [$a[1][1]], [$a[1][2]], [$a[1][3]], [$a[1][4]] ]);
$basis2 = Matrix([ [$a[2][1]], [$a[2][2]], [$a[2][3]], [$a[2][4]] ]);
$basis3 = Matrix([ [$a[5][1]], [$a[5][2]], [$a[5][3]], [$a[5][4]] ]);


$multians = MultiAnswer($basis1, $basis2, $basis3)->with(
  singleResult => 1,
  separator => ',',
  tex_separator => ',',
  allowBlankAnswers=>0,
  checker => ~~&basis_checker_columns,
);


Context()->texStrings;
BEGIN_TEXT

Let \(W\) be the subspace of \( {\mathbb R}^4\) spanned by the following vectors.
$BR

\[ 
$V1, \ \ \ \ 
$V2, \ \ \ \
$V3, \ \ \ \ 
$V4.
\]
