$s = random(-1,1,1);

$a11 = $k*$a;
$a12 = $l*$b;
$a13 = $m*$a + $n*$b;
$a14 = $n*$a - $m*$b;

$a21 = $k*$c;
$a22 = $l*$d;
$a23 = $m*$c + $n*$d;
$a24 = $n*$c - $m*$d;

$a31 = $p*$a11 + $q*$a21;
$a32 = $p*$a12 + $q*$a22;
$a33 = $p*$a13 + $q*$a23;
$a34 = $p*$a14 + $q*$a24;

$a41 = $r*$a11 + $s*$a21;
$a42 = $r*$a12 + $s*$a22;
$a43 = $r*$a13 + $s*$a23;
$a44 = $r*$a14 + $s*$a24;

$ml = $m*$l;
$kn = $k*$n;
$nl = $n*$l;

$mkl = - $k * $l;
$mkm = - $k * $m;
 
} until ($a41 != 0 or $a42 != 0 or $a43 !=0 or $a44 != 0);


