# DESCRIPTION
# Problem from Holt Linear Algebra
# WeBWorK problem written by Richard Bayne, <rbayne@howard.edu>
# ENDDESCRIPTION

## Tagged by reb 06/3/13

## DBsubject(Linear algebra)
## DBchapter(Euclidean spaces)
## DBsection(Row, column, and null spaces)
## Institution(Howard University)
## Author(Richard Bayne)
## Level(4)
## MO(1)
## MLT(basis_null_space)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('.')
## Problem1('32')
## KEYWORDS('linear algebra', 'subspaces', 'basis', 'nullity')

## Textbook tags
## \{ textbook_ref_exact("Holt Linear Algebra", "4.2","32a") \}

DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "MatrixReduce.pl",
  "parserMultiAnswer.pl",
  "PGcourse.pl"
);

Context("Matrix");

$c11 = 1;
$c21 = 0;
$c31 = 0;
$c12 = 0;
$c22 = 1;
$c32 = 0;
$c13 = random(-4,-2,1);
$c23 = 0;
$c33 = 0;
$c14 = random(2,5,1);
$c24 = random(1,3,1);
$c34 = 1;
$c15 = random(-1,1,1);
$c25 = 0;
$c35 = random(2,4,1);

#$mC = new Matrix(3,5);
#$mC->assign(1,1,$c11);
#$mC->assign(1,2,$c12);
#$mC->assign(1,3,$c13);
#$mC->assign(1,4,$c14);
#$mC->assign(1,5,$c15);
#$mC->assign(2,1,$c21);
#$mC->assign(2,2,$c22);
#$mC->assign(2,3,$c23);
#$mC->assign(2,4,$c24);
#$mC->assign(2,5,$c25);
#$mC->assign(3,1,$c31);
#$mC->assign(3,2,$c32);
#$mC->assign(3,3,$c33);
#$mC->assign(3,4,$c34);
#$mC->assign(3,5,$c35);

$mc=Matrix([
  [$c11,$c12,$c13,$c14,$c15],
  [$c21,$c22,$c23,$c24,$c25],
  [$c31,$c32,$c33,$c34,$c35]
]);

$mctrans=$mc->transpose;

#$ans1 = -$c13;
#$ans2 = 0;
#$ans3 = 1;
#$ans4 = 0;
#$ans5 = 0; 
#$ans6 = -$c15 + $c35*$c14;
#$ans7 = -$c25 + $c35*$c24;
#$ans8 =  0;
#$ans9 = -$c35;
#$ans10 = 1;

$V1 = ColumnVector(-$c13,0,1,0,0);
$V2 = ColumnVector(-$c15 + $c35*$c14, -$c25 + $c35*$c24, 0, -$c35, 1);

$multians = MultiAnswer($V1,$V2)->with(
  singleResult=>1,
  checker => sub {
    my ($correct, $student, $self)=@_;
    my ($cor1,$cor2)=@{$correct};
    my ($stu1,$stu2)=@{$student};
    #make row vectors
    $cor1 = Vector($cor1);
    $cor2 = Vector($cor2);
    $stu1 = Vector($stu1);
    $stu2 = Vector($stu2);
    my $stu = Matrix([
     [@{$stu1->{data}}],
     [@{$stu2->{data}}]
    ]);
    my $cor = Matrix([
     [@{$cor1->{data}}],
     [@{$cor2->{data}}]
    ]);
    my $redStu = rref($stu);
    my $redCor = rref($cor);
    if ($redStu->row(2)->isZero){
      Value::Error("Basis vectors must be linearly independent.");
      return 0;
    }
    if ( ($redCor - $redStu)->isZero ){
      return 1;
    }
    else {
      return 0;
    }
  }
);

TEXT(beginproblem());
Context()->texStrings;
BEGIN_TEXT
Find a basis for the null space of matrix 
A = \($mc\):
$BR
$BR
$BCENTER
\(\Bigg $LBRACE\)\{$multians->ans_array\}, \{$multians->ans_array\} 
\(\Bigg $RBRACE\)
$ECENTER
$BR

END_TEXT
Context()->normalStrings;

ANS($multians->cmp());

Context()->texStrings;

SOLUTION(EV3(<<'END_SOLUTION'));
${BBOLD}SOLUTION:${EBOLD} $PAR
\(A\) already is row-reduced, though perhaps not in echelon form. Its pivots are in the first, second and fourth columns, so the third and fifth variables are free; call them \(s_1\) and \(s_2\). Solving for the other variables one finds that the general solution to the equation \(A{\bf x}= {\bf 0}\) has the form  
$PAR
\[ {\bf x} = s_1 $V1 + s_2 $V2 \]
$PAR
so  
$PAR
\[ \Bigg $LBRACE $V1, $V2 \Bigg $RBRACE \]
is a basis for the nullspace. 
END_SOLUTION
Context()->normalStrings;

ENDDOCUMENT();

