\(\lambda_2 = \)\{ans_rule(10)\}, and \(\lambda_3 = \)\{ans_rule(10)\}.
END_TEXT
Context()->normalStrings;

ANS($e1->cmp());
ANS($e2->cmp());
ANS($e3->cmp());

