DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "PGcourse.pl"
);
TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix')->variables->are(x=>'Real');

$a = random(-10,10,1);
$b = random(-10,10,1);
$c = random(-10,10,1);
$d = random(-10,10,1);

$A = Matrix([[$a, $b], [$c, $d]]);

$neg_trace = - $a - $d;
$det = $a * $d - $b * $c;

$ans = Formula("x^2 + $neg_trace * x + $det")->reduce;

Context()->texStrings;
BEGIN_TEXT
Find the characteristic polynomial of the matrix 
\[ A = $A. \]
$PAR

We usually use the variable \(\lambda\) 
but for this problem you should use the variable \(x\) instead.
$PAR

\( p(x) = \) \{ans_rule(20)\}.
END_TEXT
Context()->normalStrings;

ANS($ans->cmp);
;
ENDDOCUMENT();

## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## Tagged by cmd6a 4/30/06

## DBsubject(Linear algebra)
## DBchapter(Eigenvalues and eigenvectors)
## DBsection(Computing eigenvalues and eigenvectors)
## Date(July 2013)
## Institution(Rochester and Hope College)
## Author(Paul Pearson)
## Level(3)
## MO(1)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('6.1')
## Problem1('')


DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "PGcourse.pl"
);
TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');

# choose eigenvalues

$one = random(-6,2,1);
$two = random($one+1, 6, 1);
while (abs($one * $two) > 20) { $two = random($one+1, 6, 1); }

# this will be an invertible matrix with determinant either 1 or -1

$a = random(-3,3,2);
$c = non_zero_random(-2,2,1);
$d = random(-3,3,2);
$det = random(-1,1,2);
$b = ($a*$d-$det)/$c;

# the inverse is then

$k = $d/$det;
$l = - $b/$det;
$m = - $c/$det;
$n = $a/$det;

# calculate the matrix 

$s = $a * $one * $k + $b * $two * $m;
$t = $a * $one * $l + $b * $two * $n;
$u = $c * $one * $k + $d * $two * $m;
$v = $c * $one * $l + $d * $two * $n;

$A = Matrix([[$s, $t], [$u, $v]]);

Context()->texStrings;
BEGIN_TEXT
Find the eigenvalues of the matrix 
\[ A= $A \]
The eigenvalues are \{ans_rule(20)\}.
$BR
(Enter your answers as a comma separated list.  The list you enter
should have repeated items if there are eigenvalues with multiplicity
greater than one.)
END_TEXT
Context()->normalStrings;

ANS(List(Compute($one),Compute($two))->cmp);
COMMENT('Two distinct real eigenvalues.');
ENDDOCUMENT();

