## DESCRIPTION
## Eigenvalues and eigenvectors of 2x2 matrix (distinct, real)
## ENDDESCRIPTION


## DBsubject(Linear algebra)
## DBchapter(Eigenvalues and eigenvectors)
## DBsection(Computing eigenvalues and eigenvectors)
## Date(11/06/2015)
## Institution(METU-NCC)
## Author(Benjamin Walter)
## MLT(find2x2eigen)
## MLTleader(1)
## Level(4)
## Static(1)
## MO(1)


##################################
#  Initialization

DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "PGmatrixmacros.pl",
  "MathObjects.pl",
  "parserMultiAnswer.pl",
  "PGcourse.pl"
);


TEXT(beginproblem());

#####################################
#  Setup

Context("Numeric");

# 1) choose eigenvalues a,bc for matrix of form
#    [ 0 -ac  ]     [ 0   ac  ]
#    [ b a+bc ]  or [ -b a+bc ]
#
# 2) phase shift to get 
#    [ p   -ac   ]
#    [ b  a+bc+p ]
#
#  eigenvalues (a+p) and (bc+p)
#  eigenvectors [c -1] and [a -b]

$a = non_zero_random(-5,5,1);
$c = random(1,3,1);
do { $b = non_zero_random(-5,5,1); } until (($b*$c != $a) and (abs($b*$c) < 10));

$neg = non_zero_random(-1,1,1);

$min = max(-9,-9-$a,-9-$b*$c);  $max = min(9,9-$a,9-$b*$c);
do { $phase = non_zero_random($min,$max,1); } until ((abs($a+$b*$c+$phase) < 12) and ($a != -$phase) and ($b*$c != -$phase));


$A11 =  $phase;  $A12 =  -$neg*$a*$c;
$A21 = $neg*$b;  $A22 =  $a+$b*$c+$phase;

$lambda1 =  Real("$a+$phase");
$v11 = Real("$c");
$v21 = Real("-$neg");

$lambda2 = Real("$b*$c+$phase");
$v12 = Real("$a");
$v22 = Real("-$neg*$b");


$multians1 = MultiAnswer($lambda1, $v11, $v21, $lambda2, $v12, $v22)->with(
    singleResult => 1,
    checkTypes => 0,
    allowBlankAnswers => 1,
    format =>  
    "<table border='0' cellspacing='0'>
    <tr>
      <td> %s, \(\Bigl\lbrack\)</td>
      <td><table border='0' cellspacing='5'><tr><td> %s </td></tr><tr><td> %s </td></tr></table></td>
      <td>\(\Bigr\rbrack\);&nbsp;&nbsp; %s, \(\Bigl\lbrack\)</td>
      <td><table border='0' cellspacing='5'><tr><td> %s </td></tr><tr><td> %s </td></tr></table></td>
      <td>\(\Bigr\rbrack\)</td>
    </tr>
    </table>",
    tex_format =>  
    "%s, \left\lbrack \begin{array}{r} %s \\ %s \end{array}\right\rbrack; \ \ 
     %s, \left\lbrack \begin{array}{r} %s \\ %s \end{array}\right\rbrack",

    checker => sub {
        my ($correct, $student, $answerHash ) = @_;
        my @c = @{$correct};
	my @s = @{$student};

        my $flag1 = 0;
        my $flag2 = 0;
        my $flag  = 0;

        Value::Error("Your vectors are parallel") if
        $c[1]->typeMatch($s[1]) &&
        $c[2]->typeMatch($s[2]) &&
        $c[4]->typeMatch($s[4]) &&
        $c[5]->typeMatch($s[5]) &&
        ($s[1] * $s[5] == $s[2] * $s[4]);
        
        if ( $c[0]->typeMatch($s[0]) && 
             $c[1]->typeMatch($s[1]) && 
             $c[2]->typeMatch($s[2]) && 
             ($s[1] != 0 || $s[2] != 0) ) 
        {
          if ( ($A11 * $s[1] + $A12 * $s[2] == $s[0] * $s[1]) &&
               ($A21 * $s[1] + $A22 * $s[2] == $s[0] * $s[2]) 
          ){
                $flag1=1;
          }
        }

        if ( $c[3]->typeMatch($s[3]) && 
             $c[4]->typeMatch($s[4]) && 
             $c[5]->typeMatch($s[5]) && 
             ($s[4] != 0 || $s[5] != 0) ) 
        {
          if ( ($A11 * $s[4] + $A12 * $s[5] == $s[3] * $s[4]) &&
               ($A21 * $s[4] + $A22 * $s[5] == $s[3] * $s[5]) 
          ){
                $flag2=1;
          }
        }

        if($flag1==1 && $flag2 ==1){
           $flag=1;
        }else{
           if ($flag1 == 1) {
              my $msg = "\((\lambda_1, \boldsymbol{\vec{v}_1})\) is correct; ";
              if (($c[3]->typeMatch($s[3])) && (($s[3] == $c[0]) || ($s[3] == $c[3])) && ($s[0] != $s[3])) {
                $msg = $msg . "and \(\lambda_2\) is correct but \(\boldsymbol{\vec{v}_2}\) is incorrect";
              } else {
                $msg = $msg . "but \(\lambda_2\) and \(\boldsymbol{\vec{v}_2}\) are incorrect";
              }
              Value::Error($msg);
           } elsif ($flag2 == 1) {
              my $msg = "\((\lambda_2, \boldsymbol{\vec{v}_2})\) is correct; ";
              if (($c[0]->typeMatch($s[0])) && (($s[0] == $c[0]) || ($s[0] == $c[3])) && ($s[0] != $s[3])) {
                $msg = $msg . "and \(\lambda_1\) is correct but \(\boldsymbol{\vec{v}_1}\) is incorrect";
              } else {
                $msg = $msg . "but \(\lambda_1\) and \(\boldsymbol{\vec{v}_1}\) are incorrect";
              }
              Value::Error($msg);
            } else {
              my $msg = "";
              if (($c[0]->typeMatch($s[0])) && (($s[0] == $c[0]) || ($s[0] == $c[3]))) {
                $msg = $msg . "\(\lambda_1\) is correct; ";
              } if (($c[3]->typeMatch($s[3])) && (($s[3] == $c[0]) || ($s[3] == $c[3])) && ($s[0] != $s[3])) {
                $msg = $msg . "\(\lambda_2\) is correct; ";
              }
              Value::Error($msg . "both eigenvectors are wrong");
            }
        }
        return $flag; 
       
    }
);



#####################################
#  Main text

Context()->texStrings;
BEGIN_TEXT
Find the eigenvalues of the matrix
\( 
\displaystyle
\mathrm{A} = 
\left\lbrack
\begin{array}{rr}
$A11 & $A12 \\
$A21 & $A22
\end{array}
\right\rbrack
\)

and find an corresponding eigenvector for each eigenvalue.
$HR

\{ mbox( [ 
'\( \lambda_1 = \) ',
$multians1->ans_rule(5),
', \( \boldsymbol{\vec{v}_1} =  \) ', 
display_matrix([[$multians1->ans_rule(5)],[$multians1->ans_rule(5)]])
] ) \}
$BR
$SPACE $SPACE and 
$BR
\{ mbox( [
'\( \lambda_2 = \) ',
$multians1->ans_rule(5),
', \( \boldsymbol{\vec{v}_2} =  \) ', 
display_matrix([[$multians1->ans_rule(5)],[$multians1->ans_rule(5)]]),
] ) \}
END_TEXT
Context()->normalStrings;

#####################################
#  Answer evaluation

$showPartialCorrectAnswers = 1;

ANS( $multians1->cmp() );

COMMENT('MathObject version.  Randomized with distinct nonzero real integer eigenvalues.');

ENDDOCUMENT();

## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## Tagged by cmd6a 5/3/06

## DBsubject(Linear algebra)
## DBchapter(Eigenvalues and eigenvectors)
## DBsection(Computing eigenvalues and eigenvectors)
## Date(July 2013)
## Institution(Rochester and Hope College)
## Author(Paul Pearson)
## Level(3)
## MO(1)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('8.3')
## Problem1('')

DOCUMENT();        # This should be the first executable line in the problem.

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "PGcourse.pl"
);

TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');
Context()->flags->set(
  tolerance => 0.001,
  tolType => "absolute",
);

$case = random(5,10,5);

if ($case==5) {
	$u[1][1] = random(1,2,1);
	$u[2][1] = 3 - $u[1][1];
} else {
        $u[1][1] = random(1,3,2);
        $u[2][1] = 4 - $u[1][1];  
}

$u[1][1] = $u[1][1] * random(-1,1,2);
$u[2][1] = $u[2][1] * random(-1,1,2);
$u[1][2] = - $u[2][1]; 
$u[2][2] = $u[1][1]; 

$U = Matrix([
[ $u[1][1], $u[1][2] ],
[ $u[2][1], $u[2][2] ],
]);

$eig1 = $case * non_zero_random(-5,-1,1) * random(0,1,1);
if ($eig1 == 0) { 
	$eig2 = $case * non_zero_random(1,5,1);
} else { 
	$eig2 = 0;
}

$E = Matrix([
[$eig1, 0],
[0, $eig2],
]);

$I = $U->inverse;

$A = $U * $E * $I;

$lambda[1] = Compute("$eig1");
$lambda[2] = Compute("$eig2");

$basis[1] = Matrix([ [$u[1][1]], [$u[2][1]] ]);
$basis[2] = Matrix([ [$u[1][2]], [$u[2][2]] ]);

Context()->texStrings;
BEGIN_TEXT
Find the eigenvalues of the matrix 
\( A = $A \)
and a corresponding eigenvector for each eigenvalue.
Scale the eigenvector, if necessary, to have integer entries (no fractions).
$HR
The smaller eigenvalue is \{ $lambda[1]->ans_rule(10) \} 
and has eigenvector \( \vec{v}_1 = \) \{ $basis[1]->ans_array(15) \}.
$BR
$BR
The larger eigenvalue is \{ $lambda[2]->ans_rule(10) \} 
and has eigenvector \( \vec{v}_2 = \) \{ $basis[2]->ans_array(15) \}.
$BR
END_TEXT
Context()->normalStrings;

foreach my $i (1..2) {

ANS($lambda[$i]->cmp);
ANS($basis[$i]->cmp(checker=>sub {
  my ( $correct, $student, $ansHash ) = @_;
  return (($student == $correct) or ($student == -1*$correct));
}));

}

COMMENT('One of the eigenvalues is zero and the other is nonzero.');
ENDDOCUMENT();

