] ) \}
END_TEXT
Context()->normalStrings;

#####################################
#  Answer evaluation

$showPartialCorrectAnswers = 1;

ANS( $multians1->cmp() );

COMMENT('MathObject version.  Randomized 3x3 matrix with 0 in cardinal positions.  Distinct nonzero real integer eigenvalues. One eigenvector is [0 1 0].');

