## DBsubject(Linear algebra)
## DBchapter(Matrix factorizations)
## DBsection(Diagonalization)
## Date(July 2013)
## Institution(Rochester and Hope College)
## Author(Paul Pearson)
## MLT(diag2x2)
## MLTleader(1)
## Level(4)
## MO(1)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('6.4')
## Problem1('')

DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "parserMultiAnswer.pl",
  "PGcourse.pl"
);
TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');

$r_sq = non_zero_random(1,6,1);
$a = non_zero_random(-9,9,1);
$d = non_zero_random(-9,9,1);
$b = non_zero_random(-.5,.5,.25);
$c = ($r_sq**2-($a - $d )**2)/(4*$b);

while( $a/$b == $c/$d ){
$r_sq += 1;
$c = ($r_sq**2-($a - $d )**2)/(4*$b);
}

## Eigen values are ($a+$d-$r_sq)/2 and ($a+$d+$r_sq)/2
$e_1 = ($a+$d-$r_sq)/2;
$e_2 = ($a+$d+$r_sq)/2;

## Eigen vectors are
$sol11 = 4*$b;
$sol12 = 4*$b;
$sol21 = 2*(-$a+$d-$r_sq);
$sol22 = 2*(-$a+$d+$r_sq);



$A = Matrix([[$a,$b],[$c,$d]]);

$S = Matrix([[ $sol11,$sol12],[$sol21,$sol22]]);
$D = Matrix([[$e_1,0],[0,$e_2]]);

$multians = MultiAnswer($S,$D)->with(
  singleResult => 0,
  allowBlankAnswers => 0,

  checker => sub {
      my ( $correct, $student, $self ) = @_;
      my @s = @{$student};
      my @c = @{$correct};
      my $S = Matrix($s[0]);
      my $D = Matrix($s[1]);

      return 0 if $S->det == Real(0);
      return 0 if ($D->element(1,2) != Real(0)) or ($D->element(2,1) != 0); 
      return $A * $S == $S * $D;
  }
);


Context()->texStrings;
BEGIN_TEXT
For the matrix 
\( A = $A \), use SAGE to
find an invertible matrix \(P\) and a diagonal matrix \(D\) 
such that \(D=P^{-1}AP\) or, equivalently, \(A = PDP^{-1}\).


$BR
$BR
$BCENTER
\(P=\) \{ $multians->ans_array(2,2,5) \}
$BR
$BR
\(D=\) \{ $multians->ans_array(2,2,5) \}
$ECENTER
END_TEXT
Context()->normalStrings;

ANS($multians->cmp);

;
ENDDOCUMENT();

# DESCRIPTION
# Diagonalize the two given matrices.
# ENDDESCRIPTION

## DBsubject(Linear algebra)
## DBchapter(Matrix factorizations)
## DBsection(Diagonalization)
## Institution(University of Missouri-Columbia)
## Author(Rick Lynch)
## MLT(diag3x3)
## Level(3)
## KEYWORDS('matrices', 'diagonalization')


###########################################################################
# initialization 
###########################################################################
DOCUMENT();
loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "contextFraction.pl",
  "parserMultiAnswer.pl",
  "PGmatrixmacros.pl",
  "PGcourse.pl"
);

TEXT(beginproblem());
$showPartialCorrectAnswers = 1;


###########################################################################
# setup contexts and variables 
###########################################################################
Context("Fraction-NoDecimals");
### Part (a)
### Matrix of form [[a,b,c], [-d,-d,d], [0,0,e]]
do {
  $a_1 = non_zero_random(-9,9,1);
  $b_1 = non_zero_random(-9,9,1);
  do {$c_1 = non_zero_random(-7,7)} until (abs($c_1) != abs($a_1) && $c_1 != $b_1);
  do {$d_1 = non_zero_random(-9,9,1)} until (abs($d_1) != abs($a_1) && abs($d_1) != abs($b_1));
  $ins_1 = ($a_1)**2 + 2*$a_1*$d_1 - 4*$b_1*$d_1 + ($d_1)**2;
  if ($ins_1 <= 0) { $ins_1 = 2 };
  $sqrt_1 = sqrt($ins_1);
  $e_1 = non_zero_random(-5,5);
  $den = $b_1*$d_1 - $a_1*($d_1+$e_1) + $e_1*($d_1+$e_1);
} until ($sqrt_1 == floor($sqrt_1) && $den != 0);
$e1_1 = Fraction($a_1-$d_1-$sqrt_1,2);
$e2_1 = Fraction($a_1-$d_1+$sqrt_1,2);
$e3_1 = $e_1;

$x11_1 = Fraction(-($a_1+$d_1-$sqrt_1),2*$d_1);
$x12_1 = Fraction(-($a_1+$d_1+$sqrt_1),2*$d_1);
$x13_1 = Fraction($b_1*$d_1+$c_1*($d_1+$e_1), $den);
$x21_1 = 1;
$x22_1 = 1;
$x23_1 = Fraction(-$d_1*($a_1+$c_1-$e_1),$den);
$x31_1 = 0;
$x32_1 = 0;
$x33_1 = 1;

$x11_1a = -($a_1+$d_1-$sqrt_1)/(2*$d_1);
$x12_1a = -($a_1+$d_1+$sqrt_1)/(2*$d_1);
$x13_1a = ($b_1*$d_1+$c_1*($d_1+$e_1))/$den;
$x21_1a = 1;
$x22_1a = 1;
$x23_1a = -$d_1*($a_1+$c_1-$e_1)/$den;
$x31_1a = 0;
$x32_1a = 0;
$x33_1a = 1;

Context()->texStrings;
$X_1 = "\left[\begin{array}{ccc} $x11_1 & $x12_1 & $x13_1\\ $x21_1 & $x22_1 & $x23_1\\$x31_1 & $x32_1 & $x33_1 \end{array}\right]";
$D_1 = "\left[\begin{array}{ccc} $e1_1 & 0 & 0 \\ 0 & $e2_1 & 0\\ 0 & 0 & $e3_1 \end{array}\right]";


### Part (b)
### Matrix of form [[a,b,-b],[b,d,-d],[-b,-d,d]]
do {
  $a = random(-4,4);
  do {$b = non_zero_random(-4,4)} until ($b != $a);
  do {$c = non_zero_random(-4,4)} until ($c != $a && $c != $b);
  $k = random(2,3,1)*random(-1,1,2);
  $e3_2 = $a - $c + $b*$k;
} until ($e3_2 != 0);
$e1_2 = 0;
$e2_2 = 0;

$x11_2 = 1;
$x12_2 = -$k;
$x13_2 = $a;
$x21_2 = 0;
$x22_2 = 1;
$x23_2 = $b;
$x31_2 = 1;
$x32_2 = 0;
$x33_2 = $c;


Context("Matrix");
$X_2 = Matrix([$x11_2, $x12_2, $x13_2], [$x21_2, $x22_2, $x23_2], [$x31_2, $x32_2, $x33_2]);
$D_2 = Matrix([$e1_2, 0, 0], [0, $e2_2, 0], [0, 0, $e3_2]);


$A_1 = Matrix([$a_1,$b_1,$c_1],[-$d_1,-$d_1,$d_1],[0,0,$e_1]);
$ans_1 = MultiAnswer($x11_1a, $x12_1a, $x13_1a, $x21_1a, $x22_1a, $x23_1a, $x31_1a, $x32_1a, $x33_1a, $e1_1, $e2_1, $e3_1)->with(
  singleResult => 1,
  checkTypes => 1,
  format => "X=(%s, %s, %s)$BR (%s, %s, %s)$BR (%s, %s, %s)$BR D=(%s, 0, 0)$BR (0, %s, 0)$BR (0, 0, %s)",
  tex_format => "X= \left[\begin{array}{ccc} %s & %s & %s \\ %s &  %s & %s \\ %s & %s & %s \end{array}\right] ,  D = \left[\begin{array}{ccc} %s & 0 & 0 \\ 0 &  %s & 0 \\ 0 & 0 & %s \end{array}\right]",
  checker => sub {
    my ($cor, $std, $self) = @_;
    @QD_r = @{$std};
    $Q = Matrix([$QD_r[0],$QD_r[1], $QD_r[2]], [$QD_r[3], $QD_r[4], $QD_r[5]],  [$QD_r[6], $QD_r[7], $QD_r[8]]);
    $D = Matrix([$QD_r[9], 0, 0], [0, $QD_r[10], 0], [0, 0, $QD_r[11]]);
    $M = ($Q->det == 0) ? $D : ($Q)*($D)*($Q->inverse);
    return ($A_1 == $M)
  }
);

$A_2 = Matrix([$a,$k*$a,-$a], [$b, $k*$b, -$b], [$c, $k*$c, -$c]);
$ans_2 = MultiAnswer($x11_2, $x12_2, $x13_2,$x21_2, $x22_2, $x23_2,$x31_2, $x32_2, $x33_2,$e1_2,$e2_2,$e3_2)->with(
  singleResult => 1,
  checkTypes => 1,
  format => "X=(%s, %s, %s)$BR (%s, %s, %s)$BR (%s, %s, %s)$BR D=(%s, 0, 0)$BR (0, %s, 0)$BR (0, 0, %s)",
  tex_format => "X= \left[\begin{array}{ccc} %s & %s & %s \\ %s &  %s & %s \\ %s & %s & %s \end{array}\right] ,  D = \left[\begin{array}{ccc} %s & 0 & 0 \\ 0 &  %s & 0 \\ 0 & 0 & %s \end{array}\right]",
  checker => sub {
    my ($cor, $std, $self) = @_;
    @QD_r = @{$std};
    $Q = Matrix([$QD_r[0],$QD_r[1], $QD_r[2]], [$QD_r[3], $QD_r[4], $QD_r[5]],  [$QD_r[6], $QD_r[7], $QD_r[8]]);
    $D = Matrix([$QD_r[9], 0, 0], [0, $QD_r[10], 0], [0, 0, $QD_r[11]]);
    $M = ($Q->det == 0) ? $D : ($Q)*($D)*($Q->inverse);
    return ($A_2 == $M)
  }
);


###########################################################################
# state the problem 
###########################################################################
Context()->texStrings;
BEGIN_TEXT
For each matrix \(A\), use SAGE to find an invertible matrix \(P\) and a diagonal matrix \(D\) 
such that \(D=P^{-1}AP\) or, equivalently, \(A = PDP^{-1}\).
$PAR
$HR
(a) \(A = $A_1\)
$PAR
\{ mbox( '\(P=\)',
	 display_matrix(
		[[ $ans_1->ans_rule(8), $ans_1->ans_rule(8), $ans_1->ans_rule(8) ],
                 [ $ans_1->ans_rule(8), $ans_1->ans_rule(8), $ans_1->ans_rule(8) ],
                 [ $ans_1->ans_rule(8), $ans_1->ans_rule(8), $ans_1->ans_rule(8) ]]),
) \}
$PAR

\{ mbox('\(\qquad D=\)',
	 display_matrix(
		[[ $ans_1->ans_rule(8), 0, 0 ],
                 [ 0, $ans_1->ans_rule(8), 0 ],
                 [ 0, 0, $ans_1->ans_rule(8) ]]),
) \}
$PAR $BR
(b) \(A = $A_2\)
$PAR
\{ mbox( '\(P=\)',
	 display_matrix(
		[[ $ans_2->ans_rule(8), $ans_2->ans_rule(8), $ans_2->ans_rule(8) ],
                 [ $ans_2->ans_rule(8), $ans_2->ans_rule(8), $ans_2->ans_rule(8) ],
                 [ $ans_2->ans_rule(8), $ans_2->ans_rule(8), $ans_2->ans_rule(8) ]]),
) \}
$PAR

\{ mbox( '\(\qquad D=\)',
	 display_matrix(
		[[ $ans_2->ans_rule(8), 0, 0 ],
                 [ 0, $ans_2->ans_rule(8), 0 ],
                 [ 0, 0, $ans_2->ans_rule(8) ]]),
) \}
END_TEXT


###########################################################################
# check the answer  
###########################################################################
ANS($ans_1->cmp());
ANS($ans_2->cmp());

BEGIN_SOLUTION
${BBOLD}Solution:${EBOLD} First, find the eigenvalues of \(A\) by solving the equation
$PAR\[
p(\lambda) = \det(A - \lambda I) = 0
\] $PAR
for \(\lambda\). Second, find an eigenvector basis for \(\mathbb{R}^3\). 
For this, find a basis for each eigenspace and then put together these eigenvectors. 
Last, construct \(P\) and \(D\). Specifically, \(P\) is the square \(3\times 3\) matrix 
whose columns are the eigenvector basis elements 
and \(D\) is the diagonal matrix whose first diagonal entry 
is the eigenvalue corresponding to the first column of \(P\), etc. This way we get that
$PAR $BR
(a) \(P = $X_1 \qquad D = $D_1\)
$PAR $BR
(b) \(P = $X_2 \qquad D = $D_2\)
$PAR
END_SOLUTION
Context()->normalStrings;

# Created in 2012. 
# Desc: Diagonalize the two given matrices.
ENDDOCUMENT();

## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## Tagged by cmd6a 4/30/06

## DBsubject(Linear algebra)
## DBchapter(Matrix factorizations)
## DBsection(Diagonalization)
## Date(July 2013)
## Institution(Rochester and Hope College)
## Author(Paul Pearson)
## Level(4)
## MO(1)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('6.3')
## Problem1('')

DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "parserPopUp.pl",
  "PGcourse.pl"
);
TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');

# choose eigenvalues

$gen = random(0,1,1);

# if gen=0 then the smaller eigenvalue is repeat; if gen=1 then the bigger eigenvalue is repeat.

if ($gen == 0) { 
	$one = random(-5,1,1);
	$two = $one;
	$three = random($one+1,5,1);
	$mult1 = 2;
	$mult2 = 1;
} else {
	$one = random(-5,1,1);
	$two = random($one+1,5,1);
	$three = $two;
	$mult1 = 1;
	$mult2 = 2;
}

# create an invertible matrix with det either 1  or -1

$a11 = random(-2,2,1);
$a21 = random(-2,2,1);
$a31 = random(-1,1,2);

$b = non_zero_random(-2,2,1);
$a12 = $b * $a11;
$m = random(-1,1,2);
$a22 = $b * $a21 + $m;
$a32 = $b * $a31;

$c = random(-2,2,1);
$d = random(-2,2,1);
$n = random(-1,1,2);
$a13 = $c * $a11 + $d * $a12 + $n;  
$a23 = $c * $a21 + $d * $a22;
$a33 = $c * $a31 + $d * $a32;

$det = - $a31 * $m * $n;

# the inverse is then

$b11 = ($a22 * $a33 - $a23 * $a32)/$det;
$b12 = - ($a12 * $a33 - $a13 * $a32)/$det;
$b13 = ($a12 * $a23 - $a13 * $a22)/$det;
$b21 = - ($a21 * $a33 - $a23 * $a31)/$det;
$b22 = ($a11 * $a33 - $a13 * $a31)/$det;
$b23 = - ($a11 * $a23 - $a13 * $a21)/$det;
$b31 = ($a21 * $a32 - $a22 * $a31)/$det;
$b32 = - ($a11 * $a32 - $a12 * $a31)/$det;
$b33 = ($a11 * $a22 - $a12 * $a21)/$det;

# calculating our matrix

$gen2 = random(0,1,1);

# if $gen2 = 0 then the matrix is diagonalizable; if $gen2 = 1 then not diagonalizable.

if ($gen2 == 0) {

	$c11 = $a11*$one*$b11 + $a12*$two*$b21 + $a13*$three*$b31;
	$c12 = $a11*$one*$b12 + $a12*$two*$b22 + $a13*$three*$b32;
	$c13 = $a11*$one*$b13 + $a12*$two*$b23 + $a13*$three*$b33;

	$c21 = $a21*$one*$b11 + $a22*$two*$b21 + $a23*$three*$b31;
	$c22 = $a21*$one*$b12 + $a22*$two*$b22 + $a23*$three*$b32;
	$c23 = $a21*$one*$b13 + $a22*$two*$b23 + $a23*$three*$b33;

	$c31 = $a31*$one*$b11 + $a32*$two*$b21 + $a33*$three*$b31;
	$c32 = $a31*$one*$b12 + $a32*$two*$b22 + $a33*$three*$b32;
	$c33 = $a31*$one*$b13 + $a32*$two*$b23 + $a33*$three*$b33;

	if ($gen == 0) { 
		$dim1 = 2; 
		$dim2 = 1; 
	} else { 
		$dim1 = 1; 
		$dim2 = 2; 
	}

	$ans = "diagonalizable";

} else {
 
	if ($gen == 0) { 

 		$c11 = $a11*$one*$b11 + ($a11+$a12*$two)*$b21 + $a13*$three*$b31;
	        $c12 = $a11*$one*$b12 + ($a11+$a12*$two)*$b22 + $a13*$three*$b32;
        	$c13 = $a11*$one*$b13 + ($a11+$a12*$two)*$b23 + $a13*$three*$b33;

	        $c21 = $a21*$one*$b11 + ($a21+$a22*$two)*$b21 + $a23*$three*$b31;
        	$c22 = $a21*$one*$b12 + ($a21+$a22*$two)*$b22 + $a23*$three*$b32;
        	$c23 = $a21*$one*$b13 + ($a21+$a22*$two)*$b23 + $a23*$three*$b33;

	        $c31 = $a31*$one*$b11 + ($a31+$a32*$two)*$b21 + $a33*$three*$b31;
        	$c32 = $a31*$one*$b12 + ($a31+$a32*$two)*$b22 + $a33*$three*$b32;
        	$c33 = $a31*$one*$b13 + ($a31+$a32*$two)*$b23 + $a33*$three*$b33;

	} else {

                $c11 = $a11*$one*$b11 + $a12*$two*$b21 + ($a12+$a13*$three)*$b31;
                $c12 = $a11*$one*$b12 + $a12*$two*$b22 + ($a12+$a13*$three)*$b32;
                $c13 = $a11*$one*$b13 + $a12*$two*$b23 + ($a12+$a13*$three)*$b33;

                $c21 = $a21*$one*$b11 + $a22*$two*$b21 + ($a22+$a23*$three)*$b31;
                $c22 = $a21*$one*$b12 + $a22*$two*$b22 + ($a22+$a23*$three)*$b32;
                $c23 = $a21*$one*$b13 + $a22*$two*$b23 + ($a22+$a23*$three)*$b33;

                $c31 = $a31*$one*$b11 + $a32*$two*$b21 + ($a32+$a33*$three)*$b31;
                $c32 = $a31*$one*$b12 + $a32*$two*$b22 + ($a32+$a33*$three)*$b32;
                $c33 = $a31*$one*$b13 + $a32*$two*$b23 + ($a32+$a33*$three)*$b33;

        }

	$dim1 = 1;
	$dim2 = 1;
	$ans = "not diagonalizable";

}

$C = Matrix([[$c11, $c12, $c13], [$c21, $c22, $c23], [$c31, $c32, $c33]]);

$popup = PopUp(["choose","diagonalizable","not diagonalizable"],$ans);

Context()->texStrings;
BEGIN_TEXT
If \(\lambda_i\) is an eigenvalue of the \(n \times n\) matrix \(A\), 
we say its \(\textbf{multiplicity}\), denoted mult\((\lambda_i)\), 
is the exponent on the factor \((\lambda - \lambda_i)\) in the characteristic polynomial for \(A\).
In order to have an eigenbasis of \(\mathbb{R}^n\), we need 
\(\text{dim}(E_{\lambda_i})= \text{ mult}(\lambda_i)\) 
for each eigenvalue \(\lambda_i\) of \(A\).
$PAR
$HR

The matrix \(A = $C \) has two distinct eigenvalues with \( \lambda_1 < \lambda_2 \). 
$BR
$BR
$PAR

Use SAGE to calculate the eigenvalues with their multiplicity 
and the eigenvectors to determine the dimension of the corresponding eigenspaces.
$BR
$BR
$PAR

The smaller eigenvalue \( \lambda_1 = \) \{ans_rule(5)\} has multiplicity \{ans_rule(5)\} and 
the dimension of the corresponding eigenspace is \{ans_rule(5)\}. 
$BR 
$BR
$PAR

The larger eigenvalue \( \lambda_2 = \) \{ans_rule(5)\} has multiplicity \{ans_rule(5)\} and 
the dimension of the corresponding eigenspace is \{ans_rule(5)\}.
$BR
$BR
$PAR

Is the matrix \(A\) diagonalizable? \{ $popup->menu \}
END_TEXT
Context()->normalStrings;

ANS(Compute("$one")->cmp);
ANS(Compute("$mult1")->cmp);
ANS(Compute("$dim1")->cmp);
ANS(Compute("$three")->cmp);
ANS(Compute("$mult2")->cmp);
ANS(Compute("$dim2")->cmp);
ANS($popup->cmp);

COMMENT('The matrix is sometimes defective and sometimes not defective.');
ENDDOCUMENT() ;

