##DESCRIPTION
##
##ENDDESCRIPTION


## DBsubject(Linear algebra)
## DBchapter(Matrices)
## DBsection(Markov chains)
## Date(6/3/2013)
## Author(Darwyn Cook)
## Level(3)
## MO(1)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('3.5')
## Problem1('18')

########################################################################

DOCUMENT();      

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "freemanMacros.pl",
  "PGcourse.pl"
);

# Print problem number and point value (weight) for the problem
TEXT(beginproblem());

# Show which answers are correct and which ones are incorrect
$showPartialCorrectAnswers = 1;

##############################################################
#
#  Setup
#
#
Context("Numeric");
Context("Matrix");

do {
$x1 = Compute(non_zero_random(0.01,0.09,0.01));
$x2 = Compute(non_zero_random(0.01,0.09,0.01));

$x21 = $x2/$x1;
} until (3*$x21 != floor(3*$x21));

$a11 = Compute("1-$x1");
$a12 = Compute("$x2");
$a21 = Compute("$x1");
$a22 = Compute("1-$x2");

$sd = 1+$x21;
$a1 = $x21/$sd;  $a2 = 1/$sd;

$A = Matrix([[$a11,$a12],[$a21,$a22]]);
$x = Matrix([[$x21/$sd],[1/$sd]]);
$dA = "\left[\begin{array}{rr} $a11 & $a12 \\ $a21 & $a22 \end{array}\right]";
$dx = "\left[\begin{array}{r} $a1 \\ $a2 \end{array}\right]";

##############################################################
#
#  Text
#
#

Context()->texStrings;
BEGIN_TEXT
\{ textbook_ref_exact("Holt Linear Algebra", "3.5","18") \}
$BR
Find all steady-state vectors for the given
stochastic matrix.
$BR
\(A = $dA\)
$BR
\(x = \)\{$x->ans_array\}

$BR
Reminder: the entries of your vector should sum to 1.
END_TEXT
Context()->normalStrings;

##############################################################
#
#  Answers
#
#

ANS($x->cmp() );

Context()->texStrings;
BEGIN_SOLUTION
${BBOLD}SOLUTION:${EBOLD} 
Solve \((A-I)\mathbf{x} = \mathbf{0}\) by row-reducing the augmented matrix
\[
\begin{array}{ccc}
\left[\begin{array}{rrr}
$a11 & $a12 & 0 \\
$a21 & $a22 & 0
\end{array}\right] &
\overset{R_1+R_2 \Rightarrow R_2}{\sim}
&
\left[\begin{array}{rrr}
$a11 & $a12 & 0 \\
0 & 0 & 0
\end{array}\right]
\end{array}
\]
and we obtain
\[
\mathbf{x} = s \left[\begin{array}{c} \frac{$x2}{$x1} \\ 1 \end{array}\right] = s \left[\begin{array}{c} $x21 \\ 1 \end{array}\right].
\]
Setting the column sum of \(\mathbf{x}\) equal to one, we need
\[
s = \frac{1}{$sd}
\]
and so
\[
\mathbf{x} = \frac{1}{$sd} \left[\begin{array}{c} $x21 \\ 1 \end{array}\right] = $dx.
\]
END_SOLUTION
Context()->normalStrings;

ENDDOCUMENT();

## DESCRIPTION
## Linear Algebra
## ENDDESCRIPTION

## Tagged by cmd6a 4/30/06

## DBsubject(Linear algebra)
## DBchapter(Inner products)
## DBsection(Computing with dot products)
## Date(July 2013)
## Institution(Rochester and Hope College)
## Author(Paul Pearson)
## Level(2)
## MO(1)
## TitleText1('Linear Algebra with Applications')
## AuthorText1('Jeffrey Holt')
## EditionText1('1')
## Section1('8.1')
## Problem1('')

DOCUMENT();        # This should be the first executable line in the problem.

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "PGchoicemacros.pl",
  "PGcourse.pl"
);

TEXT(beginproblem());
$showPartialCorrectAnswers = 1;

Context('Matrix');

@c = NchooseK(10,4);
foreach $i (0..3) { 
	$c[$i] = random(-1,1,2) * $c[$i];
}

